(117296, 5308, 2044, '<td valign="top">way too dark, I can hardly see what fruit is there</td>', 'way too dark, I can hardly see what fruit is there', '2002-09-09 12:27:00.000000', NULL, 1),
(117297, 5308, 3127, '<td valign="top">A little too dark to appreciate the fruit, but interesting idea.</td>', 'A little too dark to appreciate the fruit, but interesting idea.', '2002-09-09 14:50:00.000000', NULL, 1),
(117298, 5308, 3691, '<td valign="top">nice idea. it appears a bit grainy and unfocussed. perhaps a different color backdrop cloth too?</td>', 'nice idea. it appears a bit grainy and unfocussed. perhaps a different color backdrop cloth too?', '2002-09-09 16:01:00.000000', NULL, 1),
(117299, 5308, 811, '<td valign="top">Maybe just a touch more light and moving the bowl of fruit toward the lower left corner more would make it more powerful. karmat</td>', 'Maybe just a touch more light and moving the bowl of fruit toward the lower left corner more would make it more powerful. karmat', '2002-09-09 16:03:00.000000', NULL, 1),
(117300, 5308, 1005, '<td valign="top">Kinda dark in places, kinda over-exposed in others.  The plums don''t come across well at all.  7 Swash</td>', 'Kinda dark in places, kinda over-exposed in others.  The plums don''t come across well at all.  7 Swash', '2002-09-09 20:48:00.000000', NULL, 1),
