(119890, 5508, 3575, '<td valign="top">Very nice. Nice concept (nice title) and the lighting is beautiful.</td>', 'Very nice. Nice concept (nice title) and the lighting is beautiful.', '2002-09-09 21:37:00.000000', NULL, 1),
(119891, 5508, 2607, '<td valign="top">good idea<br/><br/></td>', 'good idea', '2002-09-09 23:40:00.000000', NULL, 1),
