INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(119901, 5508, 3087, '<td valign="top">8, Kavey</td>', '8, Kavey', '2002-09-13 07:23:00.000000', NULL, 1),
(119902, 5508, 2780, '<td valign="top">Nice idea, with a good composition, clearly taking into account the rule of thirds. The orange and green colours work well against the white background, and it is good you have used soft lighting, so that no bright areas are cast onto the fruit. One suggestion I have tho,  I think that it would look better if the peas were in the papaya, filling the hole completly, whereas at the moment they are just up the sides as far as I can tell. It just looks a bit strange.<br/>8<br/>Konador</td>', 'Nice idea, with a good composition, clearly taking into account the rule of thirds. The orange and green colours work well against the white background, and it is good you have used soft lighting, so that no bright areas are cast onto the fruit. One suggestion I have tho,  I think that it would look better if the peas were in the papaya, filling the hole completly, whereas at the moment they are just up the sides as far as I can tell. It just looks a bit strange.8Konador', '2002-09-13 11:53:00.000000', NULL, 1),
(119903, 5508, 2781, '<td valign="top">LOL, very creative!</td>', 'LOL, very creative!', '2002-09-13 19:03:00.000000', NULL, 1),
(119904, 5508, 1031, '<td valign="top">Better file your patent claim soon!</td>', 'Better file your patent claim soon!', '2002-09-14 02:39:00.000000', NULL, 1),
(119905, 5508, 1280, '<td valign="top">Clever!  Nice use of color contrasts too.  well focused.  Good job!  Good luck in the callenge.  Gracious aka Grayce</td>', 'Clever!  Nice use of color contrasts too.  well focused.  Good job!  Good luck in the callenge.  Gracious aka Grayce', '2002-09-14 14:00:00.000000', NULL, 1),
