(119910, 5508, 3880, '<td valign="top">well done!</td>', 'well done!', '2002-09-15 19:36:00.000000', NULL, 1),
(119911, 5508, 509, '<td valign="top">Great color throughout.  I like that you chose a slightly colored background as opposed to a white one.  It gives the image a warmer feel.</td>', 'Great color throughout.  I like that you chose a slightly colored background as opposed to a white one.  It gives the image a warmer feel.', '2002-09-15 23:30:00.000000', NULL, 1),
