(119913, 5509, 3084, '<td valign="top">Great yellow.</td>', 'Great yellow.', '2002-09-09 08:17:00.000000', NULL, 1),
(119914, 5509, 117, '<td valign="top">the flash and burn spots on this image have some other lighting and use a tripod</td>', 'the flash and burn spots on this image have some other lighting and use a tripod', '2002-09-09 11:43:00.000000', NULL, 1),
(119915, 5509, 2677, '<td valign="top">Slightly out of focus</td>', 'Slightly out of focus', '2002-09-09 14:01:00.000000', NULL, 1),
